1	"use client";
2	
3	import type { ReactNode } from "react";
4	import { Icon } from "@/components/nx/Icon";
5	import { CopyLine } from "./CopyLine";
6	import { Card, Row, SubNav, Hint, TAG, type SubSection } from "./ui";
7	
8	/**
9	 * Networking, on the side-rail arrangement.
10	 *
11	 * Four named sections rather than six stacked cards down one column: where this
12	 * machine answers, who may log in, what is exposed, and who may reach it. The
13	 * previous pass put all four in a single scroll of full-width slabs.
14	 *
15	 * Nothing here invents a value. A NAT server genuinely has a private address
16	 * and forwarded ports; a dedicated-IP server has neither, so it is offered a
17	 * different set of sections rather than the same set full of dashes.
18	 */
19	
20	/* `action` is a rendered node, not a callback. This panel is a client
21	   component and the page that fills it is a server component — a function prop
22	   cannot cross that boundary, and passing one crashed the tab. */
23	type Forward = {
24	  id: string; publicPort: number; guestPort: number; protocol: string;
25	  managed?: boolean; action?: ReactNode;
26	};
27	type Rule = {
28	  id: string; action: string; protocol: string; portLabel: string;
29	  sourceCidr: string; comment: string | null; enabled: boolean;
30	  manage?: ReactNode;
31	};
32	
33	type Key = "addresses" | "access" | "forwards" | "firewall";
34	
35	export function VpsNetworkingPanel({
36	  dedicated, publicIp, privateIp, ipv6, sshPort,
37	  forwards, rules,
38	  credentials, firewallPresets, addForwardForm, addRuleForm,
39	}: {
40	  dedicated: boolean;
41	  publicIp: string | null;
42	  privateIp: string | null;
43	  ipv6: string | null;
44	  sshPort: number | null;
45	  forwards: Forward[];
46	  rules: Rule[];
47	  credentials: ReactNode;
48	  firewallPresets: ReactNode;
49	  addForwardForm: ReactNode;
50	  addRuleForm: ReactNode;
51	}) {
52	  const sections: SubSection<Key>[] = [
53	    { key: "addresses", label: "Addresses", sub: "Where it answers", icon: "globe2" },
54	    { key: "access", label: "Root access", sub: "Password and SFTP", icon: "key" },
55	    ...(dedicated ? [] : [{ key: "forwards" as Key, label: "Port forwards", sub: "What is exposed", icon: "transfer" }]),
56	    { key: "firewall", label: "Firewall", sub: "Who may reach it", icon: "shield2" },
57	  ];
58	
59	  const custom = forwards.filter((f) => !f.managed);
60	
61	  return (
62	    <SubNav
63	      sections={sections}
64	      slots={{
65	        addresses: (
66	          <Card title="Addresses">
67	            <Hint>
68	              {dedicated
69	                ? "This server owns a public IP outright. Every port is reachable directly on it, with no forwarding in the way."
70	                : "This server sits behind NAT. It has a private address inside our network and reaches the outside world through forwarded ports on the shared public IP."}
71	            </Hint>
72	            <div className="flex flex-wrap gap-2">
73	              {publicIp && <CopyLine label={dedicated ? "Public IP" : "Shared public IP"} value={publicIp} />}
74	              {!dedicated && privateIp && <CopyLine label="Private IP" value={privateIp} />}
75	              {ipv6 && <CopyLine label="IPv6" value={ipv6} />}
76	              {/* No SSH command chip: the hero pins it to every tab, and Root
77	                  access carries the SFTP one. */}
78	              {!dedicated && sshPort && <CopyLine label="SSH port" value={String(sshPort)} />}
79	            </div>
80	            {!dedicated && (
81	              <p className="mt-3 text-[11.5px] leading-relaxed text-tx-faint">
82	                To reach a service you have forwarded, connect to{" "}
83	                <span className="mono text-tx-dim">{publicIp}:&lt;public port&gt;</span> — not the private
84	                address, which is only routable inside our network.
85	              </p>
86	            )}
87	          </Card>
88	        ),
89	
90	        access: credentials,
91	
92	        forwards: (
93	          <Card title="Port forwards" action={firewallPresets}>
94	            <Hint>
95	              Each forward maps a public port on the shared IP to a port inside your server. A free
96	              public port is assigned automatically; up to ten per server.
97	            </Hint>
98	            <ul className="flex flex-col">
99	              {forwards.map((f) => (
100	                <Row key={f.id}>
101	                  <span className="mono text-[12.5px] text-tx">{publicIp}:{f.publicPort}</span>
102	                  <Icon name="transfer" size={13} className="text-tx-faint" />
103	                  <span className="mono text-[12.5px] text-tx-dim">port {f.guestPort}</span>
104	                  <span className={`${TAG} border-rim-hi text-tx-dim`}>{f.protocol}</span>
105	                  <span className="ml-auto flex items-center gap-2">
106	                    {f.managed
107	                      ? <span className={`${TAG} border-sky-400/35 text-sky-300`}>Managed</span>
108	                      : f.action}
109	                  </span>
110	                </Row>
111	              ))}
112	            </ul>
113	            {custom.length === 0 && (
114	              <p className="mt-3 text-[12.5px] text-tx-faint">
115	                Only the managed SSH forward exists. Add one below to expose a web server or any other
116	                service.
117	              </p>
118	            )}
119	            <div className="mt-4 border-t border-rim-soft pt-4">{addForwardForm}</div>
120	          </Card>
121	        ),
122	
123	        firewall: (
124	          <Card title="Inbound firewall">
125	            <Hint>
126	              Which sources may reach ports inside your server. Rules apply top to bottom, first match
127	              wins, and take effect within a minute. SSH stays reachable whatever the rules say, so you
128	              cannot lock yourself out.
129	            </Hint>
130	            {rules.length === 0 ? (
131	              <p className="text-[12.5px] leading-relaxed text-tx-faint">
132	                No rules yet, so inbound traffic to forwarded ports is unrestricted. Add an{" "}
133	                <span className="font-bold text-tx-dim">Allow</span> rule to narrow that to the sources
134	                you trust.
135	              </p>
136	            ) : (
137	              <ul className="flex flex-col">
138	                {rules.map((r) => (
139	                  <Row key={r.id} dim={!r.enabled}>
140	                    <span className={`${TAG} ` + (r.action === "ALLOW"
141	                      ? "border-emerald-400/35 text-emerald-300"
142	                      : "border-rose-400/35 text-rose-300")}>
143	                      {r.action === "ALLOW" ? "Allow" : "Deny"}
144	                    </span>
145	                    <span className="mono text-[12.5px] text-tx">{r.portLabel}</span>
146	                    <span className={`${TAG} border-rim-hi text-tx-dim`}>{r.protocol}</span>
147	                    <span className="mono text-[12px] text-tx-dim">from {r.sourceCidr}</span>
148	                    {r.comment && <span className="truncate text-[12px] text-tx-faint">{r.comment}</span>}
149	                    <span className="ml-auto flex items-center gap-2">
150	                      {!r.enabled && <span className={`${TAG} border-amber-400/35 text-amber-300`}>Off</span>}
151	                      {r.manage}
152	                    </span>
153	                  </Row>
154	                ))}
155	              </ul>
156	            )}
157	            <div className="mt-4 border-t border-rim-soft pt-4">{addRuleForm}</div>
158	          </Card>
159	        ),
160	      }}
161	    />
162	  );
163	}
164

