32	    try {
33	      if (m === "light") {
34	        localStorage.setItem("nx-theme", "light");
35	        document.documentElement.setAttribute("data-theme", "light");
36	      } else {
37	        localStorage.setItem("nx-theme", "dark");
38	        document.documentElement.setAttribute("data-theme", "dark");
