57	          await page.waitForTimeout(800);
58	        } catch (e) {
59	          console.log(`click failed ${sel}: ${e.message}`);
60	        }
61	      }
62	    }
63	    const file = join(out, `${name}-${mode}.png`);
64	    await page.screenshot({ path: file, fullPage: true });
65	    console.log(`${name} [${mode}] -> ${file}`);
66	  }
67	}
