82	    click: ["Snapshots"],
83	  });
84	  await shot("vps-networking", `/dashboard/servers/${VPS_ID}?tab=networking`);
85	  await shot("vps-activity", `/dashboard/servers/${VPS_ID}?tab=activity`);
86	  await shot("vps-activity-access", `/dashboard/servers/${VPS_ID}?tab=activity`, {
87	    click: ["SSH access"],
