91	if (which === "all" || which === "game") {
92	  await shot("game-overview", `/dashboard/servers/${GAME_ID}?tab=overview`);
93	  await shot("game-console", `/dashboard/servers/${GAME_ID}?tab=console`, { wait: 3000 });
94	  await shot("game-files", `/dashboard/servers/${GAME_ID}?tab=files`, { wait: 2500 });
95	  await shot("game-services", `/dashboard/servers/${GAME_ID}?tab=services`);
96	  await shot("game-backups", `/dashboard/servers/${GAME_ID}?tab=backups`);
97	  await shot("game-networking", `/dashboard/servers/${GAME_ID}?tab=networking`);
