1	import { Icon } from "@/components/nx/Icon";
2	
3	/**
4	 * Who has been signing in to this machine.
5	 *
6	 * The `nxeon-shipper` agent has been posting SSH_LOGIN / SSH_FAILED events per
7	 * server into `TelemetryEvent` for some time; until now the only reader was the
8	 * admin monitor feed (lib/monitor-feed.ts). The customer whose server it is
9	 * could not see their own access log. This surfaces it, and nothing more — it
10	 * does not claim to be intrusion detection, and it does not score or judge the
11	 * events, because the data underneath is a login record, not a verdict.
12	 *
13	 * Servers without the agent installed report nothing, and that is said plainly
14	 * rather than drawn as an empty "0 failed logins" panel, which would read as an
15	 * all-clear the data cannot support.
16	 */
17	
18	export type AccessEvent = {
19	  id: string;
20	  type: string;
21	  ts: string;
22	  ip: string | null;
23	  user: string | null;
24	};
25	
26	const KIND: Record<string, { label: string; icon: string; ink: string; ring: string }> = {
27	  SSH_LOGIN:  { label: "Signed in",     icon: "unlock", ink: "text-emerald-300", ring: "border-emerald-400/30 bg-emerald-950/40" },
28	  SSH_LOGOUT: { label: "Signed out",    icon: "logout", ink: "text-slate-300",   ring: "border-slate-400/25 bg-slate-900/40" },
29	  SSH_FAILED: { label: "Failed sign-in", icon: "lock",  ink: "text-amber-300",   ring: "border-amber-400/30 bg-amber-950/40" },
30	};
31	
32	export function VpsAccessPanel({ events, agentSeen }: {
33	  events: AccessEvent[];
34	  /** Whether this server has ever reported telemetry at all. */
35	  agentSeen: boolean;
36	}) {
37	  if (!agentSeen) {
38	    return (
39	      <div className="card card-glass px-6 py-12 text-center">
40	        <span className="mx-auto grid h-[46px] w-[46px] place-items-center rounded-[14px] border border-rim-hi bg-well">
41	          <Icon name="shield2" size={20} />
42	        </span>
43	        <p className="mt-3.5 text-[15px] font-extrabold text-tx">No access history for this server</p>
44	        <p className="mx-auto mt-1.5 max-w-[48ch] text-[13px] leading-relaxed text-tx-dim">
45	          Sign-in history comes from the monitoring agent running on the server. This one has not
46	          reported any, so there is nothing to show — not an absence of logins.
47	        </p>
48	      </div>
49	    );
50	  }
51	
52	  return (
53	    <div className="card card-glass p-4 sm:p-5">
54	      <div className="mb-3.5">
55	        <h2 className="text-[14.5px] font-extrabold text-tx">SSH access</h2>
56	        <p className="mt-0.5 text-[12px] text-tx-faint">
57	          Sign-ins and failed attempts reported by the agent on this server.
58	        </p>
59	      </div>
60	
61	      {events.length === 0 ? (
62	        <p className="py-6 text-center text-[13px] text-tx-dim">
63	          The agent is reporting, but no sign-ins have been recorded in the retained window.
64	        </p>
65	      ) : (
66	        <ul className="flex flex-col divide-y divide-rim-soft">
67	          {events.map((e) => {
68	            const k = KIND[e.type] ?? { label: e.type, icon: "activity", ink: "text-slate-300", ring: "border-slate-400/25 bg-slate-900/40" };
69	            return (
70	              <li key={e.id} className="flex flex-wrap items-center gap-x-3 gap-y-1.5 py-2.5">
71	                <span className={`inline-flex flex-none items-center gap-1.5 rounded-full border px-2 py-1 text-[11px] font-bold ${k.ring} ${k.ink}`}>
72	                  <Icon name={k.icon} size={12} tone="inherit" />
73	                  {k.label}
74	                </span>
75	                {e.user && <span className="mono text-[12px] text-tx">{e.user}</span>}
76	                {e.ip && <span className="mono text-[12px] text-tx-dim">from {e.ip}</span>}
77	                <span className="ml-auto text-[11.5px] text-tx-faint">
78	                  {new Date(e.ts).toLocaleString()}
79	                </span>
80	              </li>
81	            );
82	          })}
83	        </ul>
84	      )}
85	    </div>
86	  );
87	}
