1	import { SPR, APP } from "@/lib/nx/sprites";
2	import { NX_ICONS, NX_ICON_TONE, type NxTone } from "@/lib/nx/icon-paths";
3	
4	/* ── one dial for icon size, site-wide ────────────────────────────────────
5	   Every mark in the system is drawn a fixed multiple of the size its call site
6	   asks for. Applying it HERE rather than editing hundreds of call sites keeps
7	   the relative sizing intact: an icon that was deliberately smaller than its
8	   neighbour stays proportionally smaller, it is just bigger in absolute terms.
9	   Change this one number to retune the whole set.
10	
11	   Note for anyone adding a primitive: scale exactly ONCE per rendered mark.
12	   `Plate` draws an `Icon` inside itself, so it scales its own BOX and passes
13	   the raw size through — scaling in both places would compound to 2.25x. */
14	export const ICON_SCALE = 1.5;
15	export const iconPx = (n: number) => Math.round(n * ICON_SCALE);
16	
17	/**
18	 * One interface mark.
19	 *
20	 * VECTOR FIRST, sprite as the fallback. `lib/nx/icon-paths.ts` carries the set
21	 * redrawn as 24x24 paths; anything it defines renders as an inline SVG in
22	 * `currentColor`, and anything it doesn't — the sheet's brand row (linux,
23	 * docker, postgres…) and the five 3D product renders — still comes off
24	 * `public/nx/nxicons.webp` exactly as before.
25	 *
26	 * Why the switch is here rather than at 137 call sites: the sprite's marks are
27	 * pre-coloured, so one inside a tinted control renders in the SHEET's colour
28	 * instead of the control's (a teal shieldcheck on a violet "Admin" chip is the
29	 * bug that started this). Routing both through one component means every call
30	 * site gets `currentColor` without being edited, and a name with no vector yet
31	 * silently keeps working.
32	 *
33	 * `size` still means what it always did — ICON_SCALE is applied here for BOTH
34	 * paths, so a swap is 1:1 and `Plate` (which sizes its box with `iconPx`)
35	 * needs no change.
36	 */
37	export function Icon({
38	  name, size = 20, className = "", style, strokeWidth = 1.8, tone,
39	}: {
40	  name: string; size?: number; className?: string; style?: React.CSSProperties;
41	  /** Outline weight for vector marks. Ignored by filled marks and the sprite. */
42	  strokeWidth?: number;
43	  /**
44	   * Override the mark's own tone. `"inherit"` hands the colour back to the
45	   * surrounding text, which is what a mark inside a tinted chip or a solid
46	   * button needs — though both of those are already handled centrally in
47	   * globals.css, so passing this is rare.
48	   */
49	  tone?: NxTone | "inherit";
50	}) {
51	  const s = iconPx(size);
52	  const vector = NX_ICONS[name];
53	
54	  if (vector) {
55	    /* The tone rides as a CLASS, never an inline style. Inline colour would
56	       beat every context rule, and context has to be able to win: a mark in
57	       an Admin chip is violet because the CHIP is, not because the sheet drew
58	       that glyph teal. See `.nx-ico*` in globals.css. */
59	    const t = tone ?? NX_ICON_TONE[name] ?? "blue";
60	    return (
61	      <svg
62	        aria-hidden
63	        width={s}
64	        height={s}
65	        viewBox="0 0 24 24"
66	        className={`nx-ico inline-block flex-none ${t === "inherit" ? "" : `nx-ico-${t}`} ${className}`}
67	        style={style}
68	        fill={vector.fill ? "currentColor" : "none"}
69	        stroke={vector.fill ? "none" : "currentColor"}
70	        strokeWidth={strokeWidth}
71	        strokeLinecap="round"
72	        strokeLinejoin="round"
73	      >
74	        <path d={vector.d} />
75	      </svg>
76	    );
77	  }
78	
79	  const [row, col] = SPR[name] ?? SPR.grid;
80	  return (
81	    <span
82	      aria-hidden
83	      className={"inline-block flex-none bg-no-repeat " + className}
84	      style={{
85	        width: s, height: s,
86	        backgroundImage: "url(/nx/nxicons.webp)",
87	        backgroundSize: `${20 * s}px ${7 * s}px`,
88	        backgroundPosition: `-${col * s}px -${row * s}px`,
89	        ...style,
90	      }}
91	    />
92	  );
93	}
94	
95	/** One mark from the 65-app third-party sheet (12 cols x 6 rows). */
96	export function AppIcon({
97	  name, size = 32, className = "",
98	}: { name: string; size?: number; className?: string }) {
99	  const [row, col] = APP[name] ?? APP.Docker;
100	  const s = iconPx(size);
101	  return (
102	    <span
103	      aria-hidden
104	      className={"inline-block flex-none bg-no-repeat " + className}
105	      style={{
106	        width: s, height: s,
107	        backgroundImage: "url(/nx/nxapps.webp)",
108	        backgroundSize: `${12 * s}px ${6 * s}px`,
109	        backgroundPosition: `-${col * s}px -${row * s}px`,
110	      }}
111	    />
112	  );
113	}
114	
115	/** An icon standing on the card ground.
116	 *
117	 * These marks are three-pass neon renders — a bordered, tinted box around one
118	 * shrinks it and competes with it. So there is no box: the glyph sits at full
119	 * size on a soft radial glow that reads as light coming off the mark itself.
120	 */
121	const GLOW: Record<string, string> = {
122	  "":  "rgba(47,110,240,0.16)",
123	  c:   "rgba(0,200,255,0.16)",
124	  v:   "rgba(150,60,255,0.16)",
125	  m:   "rgba(235,45,200,0.15)",
126	};
127	
128	export function Plate({
129	  name, size = 52, icon, tone = "", glow = true, className = "",
130	}: { name: string; size?: number; icon?: number; tone?: "" | "c" | "v" | "m";
131	     radius?: number; glow?: boolean; className?: string }) {
132	  const g = icon ?? size;                       // `size` now means the GLYPH size
133	  // The box matches the SCALED glyph; <Icon> applies the scale itself, so it
134	  // receives the raw `g` — scaling here as well would compound.
135	  const box = iconPx(g);
136	  return (
137	    <span className={"relative grid flex-none place-items-center " + className}
138	          style={{ width: box, height: box }}>
139	      {glow && (
140	        <span aria-hidden className="pointer-events-none absolute -inset-[30%] rounded-full"
141	              style={{ background: `radial-gradient(circle, ${GLOW[tone]} 0%, transparent 62%)` }} />
142	      )}
143	      <Icon name={name} size={g} className="relative" />
144	    </span>
145	  );
146	}
