3	import { useEffect, useState, type ReactNode } from "react";
4	import { Icon } from "@/components/nx/Icon";
5	import { fmtBytes } from "@/components/ui/primitives";
6	import { VpsResourceMonitor } from "./VpsResourceMonitor";
7	import { Panel, Segmented, CopyChip, Skeleton } from "./kit";
8	import type { VpsHeaderData } from "./types";
9	
10	/**
11	 * Overview — the control centre, laid out to fit one screen.
12	 *
13	 * A live figure row under the tabs, the resource monitor and insights down the
14	 * main column, and health / activity / subscription / backups / quick-connect
15	 * down the rail. Nothing here restates the hero.
16	 *
17	 * Every check and every figure is derived from a measurement, and anything
18	 * unmeasured says so rather than showing a confident green tick. That matters
19	 * most in Server health, where a tick is a claim.
20	 */
21	
22	/* ── live figures ─────────────────────────────────────────────────────── */
23	
24	function LiveStat({ icon, accent, ink, label, value, sub, pct, tone, unknown }: {
25	  icon: string; accent: string; ink: string; label: string;
26	  value: string | null; sub?: string; pct?: number; tone: string; unknown?: string;
27	}) {
28	  const known = value !== null;
29	  return (
30	    /* The colour is the CARD's — a tinted rim and its matching bloom — with the
31	       icon bare and glowing in the same hue. The plate that used to sit behind
32	       it was just a grey square swallowing the accent. */
33	    <div className="card card-glass card-i flex items-center gap-3 px-4 py-3">
34	      <Icon name={icon} size={20} tone="inherit" className={`nxp-ico flex-none ${ink}`} />
35	      <span className="flex min-w-0 flex-1 flex-col">
36	        <span className="text-[10px] font-bold uppercase tracking-[0.13em] text-tx-faint">{label}</span>
37	        <span className={"num truncate text-[17px] font-extrabold leading-tight " + (known ? "text-tx" : "text-tx-dim")}>
38	          {known ? value : "—"}
39	        </span>
40	        {known && pct !== undefined && (
41	          <span className="mt-1.5 h-[4px] w-full overflow-hidden rounded-full bg-white/10">
42	            <span className="block h-full rounded-full transition-[width] duration-700" style={{ width: `${Math.min(100, Math.max(0, pct))}%`, background: tone }} />
43	          </span>
44	        )}
45	        <span className="mt-0.5 truncate text-[10.5px] text-tx-dim">{known ? sub : unknown}</span>
46	      </span>
47	    </div>
48	  );
49	}
50	
51	/* ── server health ────────────────────────────────────────────────────── */
52	
53	type Check = { label: string; state: "ok" | "warn" | "bad" | "unknown"; note: string };
54	
55	function buildChecks(data: VpsHeaderData, diskPct: number | null): Check[] {
56	  const memPct = data.live && data.live.maxMemBytes ? (data.live.memBytes / data.live.maxMemBytes) * 100 : null;
57	  const bwPct = data.bandwidth.allowanceTB
58	    ? ((data.bandwidth.inBytes + data.bandwidth.outBytes) / (data.bandwidth.allowanceTB * 1024 ** 4)) * 100
59	    : null;
60	
61	  const lim = (v: number | null, warn: number, bad: number, okNote: string): Check["state"] =>
62	    v === null ? "unknown" : v >= bad ? "bad" : v >= warn ? "warn" : "ok";
63	
64	  return [
65	    {
66	      label: "System",
67	      state: data.status === "RUNNING" ? "ok" : data.status === "SUSPENDED" || data.status === "ERROR" ? "bad" : "warn",
68	      note: data.status === "RUNNING" ? "Operating normally" : data.status.toLowerCase(),
69	    },
70	    {
71	      label: "CPU",
72	      state: lim(data.live?.cpuPct ?? null, 80, 95, ""),
73	      note: data.live ? (data.live.cpuPct >= 80 ? `At ${data.live.cpuPct.toFixed(0)}%` : "Within limits") : "Not reported",
74	    },
75	    {
76	      label: "Memory",
77	      state: lim(memPct, 85, 95, ""),
78	      note: memPct === null ? "Not reported" : memPct >= 85 ? `At ${memPct.toFixed(0)}%` : "Within limits",
79	    },
80	    {
81	      label: "Disk",
82	      state: lim(diskPct, 80, 92, ""),
83	      note: diskPct === null ? "Not measured" : diskPct >= 80 ? `${diskPct.toFixed(0)}% full` : "Healthy",
84	    },
85	    {
86	      label: "Bandwidth",
87	      state: lim(bwPct, 80, 95, ""),
88	      note: bwPct === null ? "No allowance set" : bwPct >= 80 ? `${bwPct.toFixed(0)}% used` : "Within allowance",
89	    },
90	    {
91	      /* Reachability we can actually attest to: the hypervisor answered for
92	         this VM. We do not probe port 22 from here, so this does not claim
93	         "SSH accessible" — that would be a guess dressed as a check. */
94	      label: "Hypervisor",
95	      state: data.pveUnavailable ? "warn" : data.live ? "ok" : "unknown",
96	      note: data.pveUnavailable ? "Didn't answer" : data.live ? "Reporting" : "No reading",
97	    },
98	  ];
99	}
100	
101	const CHECK_INK: Record<Check["state"], { icon: string; ink: string }> = {
102	  ok: { icon: "checkcircle", ink: "text-emerald-300" },
103	  warn: { icon: "warntriangle", ink: "text-amber-300" },
104	  bad: { icon: "warncircle", ink: "text-rose-300" },
105	  unknown: { icon: "dotgrey", ink: "text-slate-500" },
106	};
107	
108	function HealthCard({ data, diskPct, upgradeHref }: {
109	  data: VpsHeaderData; diskPct: number | null; upgradeHref: string;
110	}) {
111	  const checks = buildChecks(data, diskPct);
112	  const scored = checks.filter((c) => c.state !== "unknown");
113	  /* The score is the share of checks that PASSED, out of the checks we could
114	     actually make — and the coverage is stated next to it, always. A "100"
115	     resting on two of six readings is a confident grade on almost no evidence,
116	     which is exactly the kind of number this tree does not render bare. Below
117	     half coverage it is withheld entirely. */
118	  const covered = scored.length;
119	  const score = covered >= checks.length / 2
120	    ? Math.round((scored.reduce((a, c) => a + (c.state === "ok" ? 1 : c.state === "warn" ? 0.5 : 0), 0) / covered) * 100)
121	    : null;
122	  const strained = checks.some((c) => c.state !== "ok" && c.state !== "unknown" && ["CPU", "Memory", "Disk", "Bandwidth"].includes(c.label));
123	
124	  const ring = score === null ? "#64748b" : score >= 90 ? "#34d399" : score >= 70 ? "#f59e0b" : "#f43f5e";
125	  const C = 2 * Math.PI * 34;
126	
127	  return (
128	    <Panel title="Server health" accent="#50b4ff" icon="shieldcheck" ink="text-sky-300">
129	      <div className="flex items-center gap-4">
130	        <div className="relative grid h-[80px] w-[80px] flex-none place-items-center">
131	          <svg viewBox="0 0 80 80" className="absolute inset-0 -rotate-90">
132	            <circle cx="40" cy="40" r="34" fill="none" stroke="rgb(120 175 255 / 0.12)" strokeWidth="7" />
133	            {score !== null && (
134	              <circle
135	                cx="40" cy="40" r="34" fill="none" stroke={ring} strokeWidth="7" strokeLinecap="round"
136	                strokeDasharray={C} strokeDashoffset={C - (score / 100) * C}
137	                style={{ transition: "stroke-dashoffset .9s cubic-bezier(.4,0,.2,1)", filter: `drop-shadow(0 0 6px ${ring}66)` }}
138	              />
139	            )}
140	          </svg>

79:          {icon && <Icon name={icon} size={15} tone="inherit" className={`nxp-ico flex-none ${ink ?? "text-[#8fb6ff]"}`} />}
139:          <span className="mt-2 h-[4px] w-full overflow-hidden rounded-full bg-white/10">
142:              style={{ width: `${Math.min(100, Math.max(0, pct))}%`, background: tone ?? "linear-gradient(90deg,#34d399,#5fd0ff)" }}
175:              (on ? "text-[#fff]" : "text-tx-dim hover:text-tx")
178:            {it.icon && <Icon name={it.icon} size={13} tone="inherit" className={on ? "text-[#fff]" : "text-[#7f9ad0]"} />}
202:      className="group inline-flex max-w-full items-center gap-2 rounded-[9px] border border-rim-soft bg-well py-1.5 pl-2.5 pr-2 transition hover:border-[#8b5cff]/45 hover:bg-hover"
