1	"use client";
2	
3	import { useEffect, useState } from "react";
4	import { Icon } from "./Icon";
5	
6	/**
7	 * Dark / light switch.
8	 *
9	 * Writes `data-theme` on <html> and remembers the choice in localStorage. The
10	 * FIRST paint is handled by an inline script in app/layout.tsx, not by this
11	 * component — a React effect runs after hydration, which is one paint too late
12	 * and shows a white flash on every load for anyone on light.
13	 *
14	 * Dark is the default and stays the product's identity; light is opt-in. The
15	 * rail and top bar are dark in both (see `.nx-dark-island` in globals.css), so
16	 * this control always sits on a dark surface and does not need to restyle
17	 * itself when the theme flips.
18	 */
19	
20	export const THEME_KEY = "nx-theme";
21	
22	export function ThemeToggle() {
23	  const [light, setLight] = useState(false);
24	
25	  /* Read what the inline script already decided, rather than deciding again —
26	     two sources of truth here is how a toggle ends up out of step with the
27	     page it is toggling. */
28	  useEffect(() => {
29	    setLight(document.documentElement.getAttribute("data-theme") === "light");
30	  }, []);
31	
32	  function toggle() {
33	    const next = !light;
34	    setLight(next);
35	    const root = document.documentElement;
36	    if (next) root.setAttribute("data-theme", "light");
37	    else root.removeAttribute("data-theme");
38	    try {
39	      localStorage.setItem(THEME_KEY, next ? "light" : "dark");
40	    } catch {
41	      /* Private mode or blocked storage. The theme still applies for this
42	         session; it just will not be remembered, which is the right failure. */
43	    }
44	  }
45	
46	  return (
47	    <button
48	      type="button"
49	      onClick={toggle}
50	      role="switch"
51	      aria-checked={light}
52	      aria-label={light ? "Switch to dark theme" : "Switch to light theme"}
53	      title={light ? "Dark theme" : "Light theme"}
54	      className="grid h-10 w-10 place-items-center rounded-[10px] text-tx-dim transition hover:bg-[rgba(72,148,255,0.08)] hover:text-white"
55	    >
56	      {/* Sun when light is ON (click to go dark), moon when dark is ON (click
57	          to go light) — the icon names the theme you'd switch TO, matching
58	          how every other toggle in the shell reads. */}
59	      <Icon name={light ? "sun" : "moon"} size={18} tone="inherit" />
60	    </button>
61	  );
62	}
