18	type OverviewFacts = ComponentProps<typeof GameOverviewPanel>["facts"];
19	
20	/**
21	 * The panel's shell: a pinned identity hero, a pinned tab rail, and one tab.
22	 *
23	 * NAVIGATION IS CONSOLIDATED from the thirteen tabs this replaced. Mods and
24	 * Plugins were two views of the same catalogue filtered by keyword, so they are
25	 * one tab with sub-tabs. The three Minecraft-only tabs are folded into the
26	 * section they belong to rather than appearing and disappearing from the rail
27	 * depending on which game you opened: Commands sits under Console (it is a
28	 * command reference for the console), History under Players, and Worlds under
29	 * Backups (they are save directories).
30	 *
31	 * The tab also lives in the URL properly now. The old shell wrote `?tab=` with
32	 * `history.replaceState`, which meant the browser back button skipped the whole
33	 * panel and a link to a tab could not be shared — and two worker notifications
34	 * deep-link into tabs, one of them to a `?tab=game settings` key that never
35	 * existed.
36	 */
37	
38	type TabKey =
39	  | "overview" | "console" | "files" | "mods" | "backups"
40	  | "players" | "schedules" | "build" | "settings" | "activity";
41	
42	const TABS: { key: TabKey; label: string; icon: string; badge?: string }[] = [
43	  { key: "overview",  label: "Overview",        icon: "donut" },
44	  { key: "console",   label: "Console",         icon: "terminal" },
45	  { key: "files",     label: "Files",           icon: "folder" },
46	  { key: "mods",      label: "Mods & Plugins",  icon: "cube" },
47	  { key: "backups",   label: "Backups",         icon: "archive" },
48	  { key: "players",   label: "Players",         icon: "users2" },
49	  { key: "schedules", label: "Schedules",       icon: "calendar" },
50	  /* Build with AI earns a tab rather than a card at the bottom of Overview,
51	     where it sat below three other panels and off the fold. It is a workflow —
52	     describe, Claude plans, you approve, we run it — not a widget. */
53	  { key: "build",     label: "Build with AI",   icon: "sparkles", badge: "AI" },
54	  { key: "settings",  label: "Settings",        icon: "gear" },
55	  { key: "activity",  label: "Activity",        icon: "activity" },
56	];
57	
58	/** Old deep-links and worker notifications still point at the retired keys. */
59	const ALIASES: Record<string, TabKey> = {
60	  plugins: "mods",
61	  worlds: "backups",
62	  commands: "console",
63	  history: "players",
64	  manage: "settings",
65	  ai: "build",
66	  buildai: "build",
67	  "game settings": "settings",
68	  gamesettings: "settings",
69	  networking: "settings",
70	  resize: "settings",
71	};
72	
73	function resolveTab(raw: string | undefined): TabKey {
74	  const k = (raw ?? "").toLowerCase().trim();
75	  if (TABS.some((t) => t.key === k)) return k as TabKey;
76	  return ALIASES[k] ?? "overview";
77	}
