144	                type="button"
145	                onClick={() => go(t.key)}
146	                aria-current={on ? "page" : undefined}
147	                className={
148	                  "inline-flex flex-none items-center gap-2 whitespace-nowrap rounded-[10px] px-3.5 py-2 text-[13px] font-semibold transition " +
149	                  (on
150	                    ? "bg-[linear-gradient(120deg,rgba(80,40,190,.55),rgba(30,44,130,.42))] text-white shadow-[inset_0_0_0_1px_rgba(139,92,255,.5)]"
151	                    : "text-tx-dim hover:bg-white/[0.05] hover:text-tx")
152	                }
153	              >
154	                <Icon name={t.icon} size={14} tone="inherit" className={on ? "text-[#fff]" : "text-tx-dim"} />
155	                {t.label}
156	                {t.badge && (
