158	                    {t.badge}
159	                  </span>
160	                )}
161	              </button>
162	            );
163	          })}
164	        </nav>
165	      </div>
166	
167	      <div className="min-w-0">
168	        {tab === "overview" && (
169	          <GameOverviewPanel
170	            serverId={serverId}
171	            gameFamily={gameFamily}
172	            data={header}
173	            facts={facts}
174	            onNavigate={(t) => go(resolveTab(t))}
175	          />
176	        )}
177	
178	        {tab === "console" && (
179	          <div className="flex flex-col gap-3">
180	            {isMc && (
181	              <SubTabs
182	                value={consoleView}
