185	              />
186	            )}
187	            {consoleView === "live" || !isMc
188	              ? <GameConsole serverId={serverId} running={header.running} />
189	              : <div className={LEGACY_CARDS}><GameCommandLibrary serverId={serverId} running={header.running} /></div>}
190	          </div>
191	        )}
192	
193	        {tab === "files" && filesPanel}
194	
195	        {tab === "mods" && (
196	          <div className="flex flex-col gap-3">
197	            <SubTabs
198	              value={modScope}
199	              onChange={setModScope}
200	              items={[{ key: "mods", label: "Mods" }, { key: "plugins", label: "Plugins" }]}
201	            />
202	            <ModsPanel serverId={serverId} scope={modScope} />
203	          </div>
204	        )}
205	
206	        {tab === "backups" && (
207	          <div className="flex flex-col gap-4">
208	            {backupsPanel}
209	            {isMc && <GameWorlds serverId={serverId} running={header.running} />}
210	          </div>
211	        )}
212	
213	        {tab === "players" && (
214	          <div className="flex flex-col gap-3">
215	            {isMc && (
216	              <SubTabs
217	                value={playersView}
218	                onChange={setPlayersView}
219	                items={[{ key: "live", label: "Online & access" }, { key: "history", label: "Session history" }]}
220	              />
221	            )}
222	            <div className={LEGACY_CARDS}>
223	              {playersView === "live" || !isMc
224	                ? <GamePlayersHub serverId={serverId} running={header.running} playersMax={header.players.max} isMc={isMc} />
225	                : <GamePlayerHistory serverId={serverId} />}
