242	}
243	
244	function SubTabs<T extends string>({
245	  value, onChange, items,
246	}: {
247	  value: T; onChange: (v: T) => void; items: { key: T; label: string }[];
248	}) {
249	  return (
250	    <div className="flex w-fit gap-1 rounded-[11px] border border-rim-hi bg-[rgba(6,14,36,.72)] p-1">
251	      {items.map((i) => (
