1	// One-off audit script for agent D (VPS panel other tabs, game panel, free-mc).
2	// Delete when done per repo convention.
3	import { chromium } from "playwright";
4	import { mkdirSync } from "node:fs";
5	import { join } from "node:path";
6	
7	const BASE = process.env.BASE_URL || "https://v2.q4w8zt3ky6vn2sm.nxeon.cloud";
8	const EMAIL = process.env.NX_EMAIL || "admin@nxeon.local";
9	const PASS = process.env.NX_PASS || "iCwEt7PDdo0ne3YM";
10	const out = process.argv[2] || "/tmp/audit-d";
11	mkdirSync(out, { recursive: true });
12	
13	const browser = await chromium.launch();
14	const ctx = await browser.newContext({ viewport: { width: 1600, height: 1100 }, deviceScaleFactor: 1 });
15	const page = await ctx.newPage();
16	
17	await page.goto(`${BASE}/login`, { waitUntil: "domcontentloaded" });
18	try {
19	  await page.click('text=Got it', { timeout: 4000 });
20	} catch {}
21	await page.fill('input[type="email"], input[name="email"]', EMAIL);
22	await page.fill('input[type="password"], input[name="password"]', PASS);
23	await Promise.all([
24	  page.waitForURL((u) => !u.pathname.includes("/login"), { timeout: 45000 }).catch(() => {}),
25	  page.click("button.btn-primary"),
26	]);
27	await page.waitForTimeout(1500);
28	console.log("post-login url:", page.url());
29	
30	async function setTheme(mode) {
31	  await page.evaluate((m) => {
32	    try {
33	      if (m === "light") {
34	        localStorage.setItem("nx-theme", "light");
35	        document.documentElement.setAttribute("data-theme", "light");
36	      } else {
37	        localStorage.setItem("nx-theme", "dark");
38	        document.documentElement.setAttribute("data-theme", "dark");
39	      }
40	    } catch {}
41	  }, mode);
42	}
43	
44	async function shot(name, path, opts = {}) {
45	  for (const mode of ["dark", "light"]) {
46	    try {
47	      await page.goto(`${BASE}${path}`, { waitUntil: "networkidle", timeout: 60000 });
48	    } catch {
49	      await page.waitForTimeout(2000);
50	    }
51	    await setTheme(mode);
52	    await page.waitForTimeout(opts.wait || 1500);
53	    if (opts.click) {
54	      for (const sel of opts.click) {
55	        try {
56	          await page.locator(`button:has-text("${sel}")`).first().click({ timeout: 12000 });
57	          await page.waitForTimeout(800);
58	        } catch (e) {
59	          console.log(`click failed ${sel}: ${e.message}`);
60	        }
61	      }
62	    }
63	    const file = join(out, `${name}-${mode}.png`);
64	    await page.screenshot({ path: file, fullPage: true });
65	    console.log(`${name} [${mode}] -> ${file}`);
66	  }
67	}
68	
69	const args = process.argv.slice(3);
70	const which = args[0] || "all";
71	
72	const VPS_ID = "cmtot7pos0005hlf08v1zwbg1"; // db-primary.nxeon.cloud
73	const GAME_ID = "cmtot7ppn000bhlf06ssy6lsm"; // mc-survival.nxeon.cloud
